from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak
from reportlab.lib.styles import ParagraphStyle
B = ParagraphStyle('b', fontName='Times-Roman', fontSize=11, leading=16, spaceAfter=8)
H1 = ParagraphStyle('h1', fontName='Times-Bold', fontSize=15, leading=20, spaceAfter=12, spaceBefore=6)
H2 = ParagraphStyle('h2', fontName='Times-Bold', fontSize=12, leading=16, spaceAfter=6, spaceBefore=6)
T = ParagraphStyle('t', fontName='Times-Bold', fontSize=18, leading=24, alignment=1)
C = ParagraphStyle('c', fontName='Times-Roman', fontSize=11, leading=16, alignment=1)
s = []
P = lambda t, st=B: s.append(Paragraph(t, st))
P('ANTHROPOMORPHISM, SELF-DISCLOSURE AND WELL-BEING AMONG GENERATION Z USERS OF CONVERSATIONAL AGENTS IN MALAYSIA', T); s.append(Spacer(1, 30))
P('NUR FARHANA BINTI AHMAD', C); P('A thesis submitted in fulfilment of the requirements for the award of the degree of Doctor of Philosophy', C); P('Faculty of Social Sciences and Humanities, Example University of Technology', C); P('2026', C); s.append(PageBreak())
P('TABLE OF CONTENTS', H1)
for t in ['1.1 Introduction ........ 1', '1.2 Background of the Study ........ 2', '1.3 Problem Statement ........ 4', '1.4 Research Questions ........ 5', '1.5 Research Objectives ........ 6']: P(t)
s.append(PageBreak())
P('ABSTRACT', H1); P('Conversational agents are now part of daily life for many young adults. This study examined how anthropomorphism relates to self-disclosure and psychological well-being among Generation Z users in Malaysia. A total of 412 respondents completed an online survey. Anthropomorphism predicted greater self-disclosure (β = .38, p < .001), and self-disclosure was associated with higher well-being (β = .21, p < .01). Self-disclosure partially mediated the relationship between anthropomorphism and well-being.')
s.append(PageBreak())
P('CHAPTER 1 INTRODUCTION', H1)
P('1.1 Introduction', H2); P('Conversational agents such as ChatGPT and Replika have moved from novelty to daily companions for many young people. Generation Z users talk to these systems about their studies, their worries and their relationships. This chapter introduces the study, its background, the problem it addresses and its objectives.')
P('1.2 Background of the Study', H2); P('Anthropomorphism is the tendency to attribute human characteristics, motivations and emotions to non-human agents. Users who perceive a chatbot as human-like often treat it as a social partner rather than a tool. Research on social presence suggests that human-like cues encourage people to share personal information. In Malaysia, more than 80% of young adults use at least one conversational agent each week. Self-disclosure is known to support well-being when it leads to feeling understood and supported.')
P('1.3 Problem Statement', H2); P('Despite rapid adoption, little is known about how anthropomorphism shapes what young users disclose to conversational agents. Most studies have been conducted in Western samples, and evidence from Southeast Asia remains scarce. Existing findings on chatbot use and well-being are also inconsistent, with some studies reporting benefits and others reporting increased loneliness. Without this evidence, designers and counsellors lack guidance on healthy use.')
P('1.4 Research Questions', H2); P('This study seeks to answer the following research questions: RQ1: What is the level of anthropomorphism perceived by Generation Z users of conversational agents? RQ2: Is anthropomorphism associated with self-disclosure to conversational agents? RQ3: Does self-disclosure mediate the relationship between anthropomorphism and psychological well-being?')
P('1.5 Research Objectives', H2); P('The objectives of this study are: (i) to identify the level of anthropomorphism perceived by Generation Z users; (ii) to examine the relationship between anthropomorphism and self-disclosure; and (iii) to determine the mediating role of self-disclosure in the relationship between anthropomorphism and psychological well-being.')
P('1.6 Conceptual Framework', H2); P('The framework is based on Social Penetration Theory and the Computers Are Social Actors paradigm. In this framework, anthropomorphism is the independent variable, psychological well-being is the dependent variable, and self-disclosure is the mediating variable. Loneliness is examined as the moderating variable.')
P('1.7 Scope of the Study', H2); P('This study focuses on Generation Z university students aged 18 to 27 years in Peninsular Malaysia. Data were collected between March and June 2025 through an online questionnaire. The study is limited to text-based conversational agents and does not include voice assistants.')
P('1.8 Significance of the Study', H2); P('Theoretically, this study extends Social Penetration Theory to human-AI interaction by testing self-disclosure as a mechanism. Practically, the findings can inform designers of conversational agents about features that encourage healthy disclosure. The results will also help university counsellors understand how students use chatbots for emotional support.')
s.append(PageBreak())
P('CHAPTER 3 RESEARCH METHODOLOGY', H1)
P('3.1 Research Design', H2); P('This study used a quantitative cross-sectional survey design. Data were analysed with partial least squares structural equation modelling.')
P('3.2 Phase 1: Instrument Development', H2); P('The questionnaire was adapted from validated scales and reviewed by three experts in psychology and human-computer interaction.')
P('3.3 Phase 2: Pilot Study', H2); P('A pilot study with 40 respondents confirmed the reliability of all scales, with Cronbach alpha values above .80.')
P('3.4 Phase 3: Main Data Collection', H2); P('A total of 412 respondents were recruited through purposive sampling from five public universities.')
P('3.5 Phase 4: Data Analysis', H2); P('The measurement and structural models were assessed using SmartPLS 4, and mediation was tested with bootstrapping of 5,000 samples.')
s.append(PageBreak())
P('CHAPTER 4 RESULTS', H1)
P('4.1 Respondent Profile', H2); P('Of the 412 respondents, 63% were female and the mean age was 21.4 years (SD = 2.1). Most respondents used ChatGPT, followed by Character.AI and Replika.')
P('4.2 Level of Anthropomorphism', H2); P('The mean level of anthropomorphism was moderate (M = 3.42, SD = 0.71). Respondents most often described their chatbot as friendly and understanding.')
P('4.3 Structural Model', H2); P('Anthropomorphism significantly predicted self-disclosure (β = .38, p < .001). Self-disclosure was associated with higher psychological well-being (β = .21, p < .01). The indirect effect of anthropomorphism on well-being through self-disclosure was significant (β = .08, 95% CI [.03, .14]), indicating partial mediation. Loneliness strengthened the link between anthropomorphism and self-disclosure.')
s.append(PageBreak())
P('CHAPTER 5 DISCUSSION AND CONCLUSION', H1)
P('5.1 Discussion', H2); P('The findings show that users who see conversational agents as more human-like disclose more personal information. This pattern supports the Computers Are Social Actors paradigm. Disclosure in turn was linked to modest gains in well-being, which suggests that chatbots can offer a space to express feelings.')
P('5.2 Implications', H2); P('Theoretically, the results extend Social Penetration Theory by showing that disclosure to a non-human partner follows similar processes. Practically, designers should balance human-like features with clear reminders that the agent is not a human. University counselling services could use these findings to guide students on healthy chatbot use.')
P('5.3 Recommendations', H2); P('Universities should include digital well-being and AI literacy in student orientation programmes. Developers should provide transparent information on how disclosed data are stored and used. Counsellors should ask students about their chatbot use as part of routine assessment.')
P('5.4 Limitations', H2); P('The cross-sectional design prevents causal conclusions, and all measures were self-reported.')
P('5.5 Suggestions for Future Research', H2); P('Future research should use longitudinal designs to test whether disclosure to chatbots predicts later well-being. Future studies should also include older adults and voice-based agents. Experimental studies could manipulate human-like cues to test their causal effect on disclosure.')
P('5.6 Conclusion', H2); P('Anthropomorphism encourages young Malaysians to open up to conversational agents, and this openness is linked to better well-being. Healthy design and guidance can help young users benefit while staying safe.')
P('REFERENCES', H1); P('Nass, C., and Moon, Y. (2000). Machines and mindlessness. Journal of Social Issues, 56, 81-103.')
SimpleDocTemplate('thesis.pdf', pagesize=A4).build(s)
